5	export function handle(req: HttpRequest, db: ItemDb): HttpResponse {
6	  if (req.path === '/items' && req.method === 'GET') {
7	    return { status: 200, headers: {}, body: [...db.values()] };
8	  }
9	  const m = /^\/items\/([^/]+)$/.exec(req.path);
10	  if (m) {
11	    if (req.method === 'GET') {
12	      const item = db.get(m[1]);
13	      return item ? ok(item) : fail(404, 'not_found', `Item ${m[1]} not found`);
14	    }
15	    if (req.method === 'PATCH') return patchItem(db, m[1], req);
16	    return fail(405, 'method_not_allowed', `Method ${req.method} not allowed`);
17	  }
18	  return fail(404, 'not_found', `No route for ${req.path}`);
19	}

