5	function obj(v: unknown, where: string): Record<string, unknown> {
6	  if (typeof v !== 'object' || v === null || Array.isArray(v)) throw new SchemaError(`${where}: expected object`);
7	  return v as Record<string, unknown>;
8	}
9	
10	export function parseItem(v: unknown): Item {
11	  const o = obj(v, 'item');
12	  if (typeof o.id !== 'string') throw new SchemaError('item.id: expected string');
13	  if (typeof o.title !== 'string') throw new SchemaError('item.title: expected string');
14	  if (typeof o.done !== 'boolean') throw new SchemaError('item.done: expected boolean');
15	  if (typeof o.version !== 'number' || !Number.isInteger(o.version) || o.version < 1) {
16	    throw new SchemaError('item.version: expected positive integer');
17	  }
18	  return { id: o.id, title: o.title, done: o.done, version: o.version };
19	}
20	
21	export function parseItems(v: unknown): Item[] {
22	  if (!Array.isArray(v)) throw new SchemaError('items: expected array');
23	  return v.map(parseItem);
24	}
25	
26	export function parseApiError(v: unknown): ApiErrorBody {
27	  const e = obj(obj(v, 'body').error, 'error');
28	  if (typeof e.code !== 'string' || typeof e.message !== 'string') throw new SchemaError('error: code and message are strings');
29	  const out: ApiErrorBody = { code: e.code, message: e.message };
30	  if (e.current !== undefined) out.current = parseItem(e.current);
31	  return out;
32	}

